def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    result = []

    for cls in classes:
        while cls in seen:
            cls = cls.__bases__[0]
        seen.add(cls)
        result.append(cls)

    return result

