def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    def normalize(i):
        if i is None:
            if output is not None:
                return output()
        if isinstance(i, DeclarationToken):
            return i
        if isinstance(i, DeclarationType):
            return i.association
        if isinstance(i, DeclarationComposite):
            return normalize(i.value)
        if isinstance(i, DeclarationSequence):
            return normalize(i.sequence)#Expand the sequence
        if isinstance(i, DeclarationImplementTypes):
            for impl in i.implementationTypes:
                return _normalizeargs(impl, output)
        raise ValueError(f"Unexpected declaration argument: {i}")
    return [normalize(i) for i in sequence]

