            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for obs in observer_schema['observed_fields']:
        if obs not in response:
            raise KeyError(f"Observed field {obs} is not present in the Kubernetes response")

        if obs == 'items':
            if 'items' not in last_applied_manifest:
                last_applied_manifest['items'] = []
            for item in response['items']:
                if item not in last_applied_manifest['items']:
