        version_number = None
        if version.startswith('0'):
            version_number = int(version[1:])
        else:
            version_number = int(version)

        next_version_number = version_number + 1

        if not next_version_number > 0:
            raise ValueError("Current version must be positive.")

        if next_version_number < 9:
            return '0' + str(next_version_number)
        else:
            return str(next_version_number)

