def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    """

    if not isinstance(rendered_config, dict) or not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be of type str or dict")

    if not isinstance(config_filename, str):
        raise TypeError("config_filename must be of type str")

    config_dir = os.path.dirname(config_filename)
    if config_dir and not os.path.exists(config_dir):
        os.makedirs(config_dir)

    if os.path.exists(config_filename):
        if not overwrite:
            raise IOError(f"File {config_filename} already exists, use overwrite=True to overwrite.")
        os.remove(config_filename)

    with open(config_filename, 'w') as f:
