    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, (tuple, list)):
        sequence = seq
        type_ = type(seq)
    elif hasattr(seq, '__iter__'):
        sequence = tuple(seq)
        type_ = type(seq)
    else:
