def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    if tentative or not iface.providedBy(candidate):
        if not tentative:
            raise zope.interface.Invalid(f"Package {candidate.getPhysicalPath()} does not provide interface {iface.__name__}")

    def verify_method(name):
        method = getattr(candidate, name, None)
        if method is None:
            raise zope.interface.Invalid(f"Package {candidate.getPhysicalPath()} is missing required method {name}")

       sig = iface.getSignature(name, vtype if vtype else None)
        if not sig:
            raise zope.interface.Invalid(f"Package {candidate.getPhysicalPath()} missing method {name}")

        if method.__code__.co_argcount != sig.numParams:
            raise zope.interface.Invalid(f"Package {candidate.getPhysicalPath()} method {name} has {method.__code__.co_argcount} arguments, expected {sig.numParams}")

        if method.__code__.co_kwonlyargs:
            raise zope.interface.Invalid(f"Package {candidate.getPhysicalPath()} method {name} does not support keyword-only arguments")

        for param in sig.params:
            if param.kind == param.VAR_POSITIONAL:
                raise zope.interface.Invalid(f"Package {candidate.getPhysicalPath()} method {name} does not support variable positional parameters")

        for attr in sig.attrs:
            if attr.kind == attr.PROPERTY:
                raise zope.interface.Invalid(f"Package {candidate.getPhysicalPath()} method {name} does not support properties")

    def verify_attribute(name):
        attr = getattr(candidate, name, None)
        if attr is None:
            raise zope.interface.Invalid(f"Package {candidate.getPhysicalPath()} is missing required attribute {name}")

    for name in iface.signature:
        verify_method(name)

    for name, attr in sorted(iface.attributes.items()):
        verify_attribute(name)

