from typing import Any, List, Union
from zope.interface import providedBy

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    if tentative:
        if iface.providedBy(candidate):
            return True
        else:
            errors.append("The candidate{} does not provide the interface {}".format(Bcolors.YELLOW, iface))
            return False

    if not iface.providedBy(candidate):
        errors.append("The candidate{} does not provide the interface {}".format(Bcolors.YELLOW, iface))

    try:
        for method in iface.implementedBy(candidate):
            if isinstance(method, type) and issubclass(candidate, method):
                try:
                    method()(candidate)
                except Exception as e:
                    errors.append(f"The method `{method.__name__}` on type `{candidate.__name__}` raised an exception: {e}")
            else:
                try:
                    if callable(method):
                        method(candidate)
                    else:
                        if hasattr(candidate, method):
                            getattr(candidate, method)()
                        else:
                            raise zope.interface.Invalid(f"The candidate{Bcolors.YELLOW} does not implement the method `{method}`")
                except Exception as e:
                    errors.append(f"The method `{method.__name__}` on type `{candidate.__name__}` raised an exception: {e}")
    except Exception as e:
        errors.append("Exception occurred while verifying methods: {}".format(e))

    if not errors:
        return True

    if len(errors) > 1:
        legacy_error = errors[-1]  # The last error is the most recent check
        for e in errors[:-1]:
            if isinstance(e, List) and isinstance(legacy_error, str):
                legacy_error += f" (and {', '.join(e)})"
            elif isinstance(e, str) and isinstance(legacy_error, List):
                legacy_error = f"{', '.join(legacy_error)} (and {e})"
            else:
                legacy_error += f" and {e}"
        legacy_error += f". Check the {__name__}.log for more details."
    else:
        legacy_error = errors[0]

    errors.insert(0, f"Only the following error was found:")
    legacy_error = "\n".join(errors)

    if len(errors) == 1:
        legacy_error = str(legacy_error)

    raise zope.interface.Invalid(legacy_error)

