def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # First, check if the explicit __metaclass__ is provided
    if explicit_mc is not None:
        return explicit_mc

    # If not, try to guess the metaclass from the bases
    for base in bases:
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__

    # If no metaclass is found, raise an error
    raise TypeError("No metaclass provided and could not guess it from thebases.")

